from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts.pages import v22r2, v23r1
from taf.selenium.sbts.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts.pages.panels.view import ViewPanel


class Diagnostic(v23r1.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._debug_tracing = DebugTracingPage(driver)
        self._ip_security_association = IpSecurityAssociationsPage(driver)

    @property
    def ip_security_association(self):
        return self._ip_security_association


class DebugTracingPage(v22r2.diagnostic.DebugTracingPage):
    def __init__(self, driver):
        super(DebugTracingPage, self).__init__(driver)
        self._view_panel = DebugTracingPageViewPanel(driver)

    def configure_iq_capture(self, enable_capture_on_event, ul_subcell_index_list=None,
                             dl_subcell_index_list=None, lte_ul_cell_ids=None, lte_dl_cell_ids=None):
        self._detail_panel.close_details_panel()
        self._view_panel.configure_iq_capture(enable_capture_on_event=enable_capture_on_event,
                                              ul_subcell_index_list=ul_subcell_index_list,
                                              dl_subcell_index_list=dl_subcell_index_list,
                                              lte_ul_cell_ids=lte_ul_cell_ids,
                                              lte_dl_cell_ids=lte_dl_cell_ids)

    def save_iq_capture(self, sfn_value, slot_value, capture_mode):
        self._detail_panel.close_details_panel()
        self._view_panel.save_iq_capture(sfn_value=sfn_value,
                                         slot_value=slot_value,
                                         capture_mode=capture_mode)


class DebugTracingPageViewPanel(v22r2.diagnostic.DebugTracingPageViewPanel):
    _LTE_UL_CELL_IDS = "LTE UL cell IDs"
    _LTE_DL_CELL_IDS = "LTE DL cell IDs"
    _LTE_CELL_IDS_INPUT_XPATH = '//section[@class="uPlane-component"]//div[contains(text(), "{}")]/parent::*//input'
    _CAPTURE_MODE = 'Capture mode'
    _CAPTURE_MODE_DROPDOWN_BUTTON_XPATH = ('//section[@class="uPlane-component"]//div[contains(text(), '
                                           '"Capture mode")]/following-sibling::div//button')
    _CAPTURE_MODE_DROPDOWN_SELECTION_XPATH = '//span[text()="{}"]/ancestor::li'
    _UL_SUBCELL = "NR UL L1 subcell list"
    _DL_SUBCELL = "NR DL L1 subcell list"

    def __init__(self, driver):
        super(DebugTracingPageViewPanel, self).__init__(driver)

    def configure_iq_capture(self, enable_capture_on_event, ul_subcell_index_list=None,
                             dl_subcell_index_list=None, lte_ul_cell_ids=None, lte_dl_cell_ids=None):
        elem = self.driver.find_element_by_xpath(self._L1_IQ_CAPTURE_XPATH)
        self._scroll_elem_into_view(elem)
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_operation(self._COMPONENT_TYPE, self._CONFIGURE)
        self._select_subcell_list(self._UL_SUBCELL, ul_subcell_index_list)
        self._select_subcell_list(self._DL_SUBCELL, dl_subcell_index_list)
        self._input_cell_ids(self._LTE_UL_CELL_IDS, lte_ul_cell_ids)
        self._input_cell_ids(self._LTE_DL_CELL_IDS, lte_dl_cell_ids)
        self.select_checkbox_by_specified_status(enable_capture_on_event,
                                                 self._CAPTURE_EVENT_INPUT_XPATH,
                                                 self._CAPTURE_EVENT_CHECKOUT_XPATH)
        self.click_enabled_element((By.XPATH, self._APPLY_CONFIGURATION_BUTTON_XPATH))

    def save_iq_capture(self, sfn_value, slot_value, capture_mode):
        if capture_mode is None:
            raise AttributeError('param capture_mode can not be None')
        elem = self.driver.find_element_by_xpath(self._L1_IQ_CAPTURE_XPATH)
        self._scroll_elem_into_view(elem)
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_operation(self._COMPONENT_TYPE, self._SAVE_IQ)
        self._input_subcell_index_and_other_fields(self._SFN, sfn_value)
        self._input_subcell_index_and_other_fields(self._SLOT, slot_value)
        self.expand_dropdown_list_and_return_elements(
            (By.XPATH, self._CAPTURE_MODE_DROPDOWN_BUTTON_XPATH.format(self._CAPTURE_MODE)),
            (By.XPATH, self._CAPTURE_MODE_DROPDOWN_SELECTION_XPATH.format(capture_mode))
        )
        elem = self.driver.find_element_by_xpath(self._CAPTURE_MODE_DROPDOWN_BUTTON_XPATH.format(self._CAPTURE_MODE))
        self._scroll_elem_into_view(elem, "start", "nearest")
        try:
            self.select_element_from_dropdown_list_by_text_and_click(
                capture_mode,
                (By.XPATH, self._CAPTURE_MODE_DROPDOWN_BUTTON_XPATH.format(self._CAPTURE_MODE)),
                (By.XPATH, self._CAPTURE_MODE_DROPDOWN_SELECTION_XPATH.format(capture_mode))
            )
        except TimeoutException and AttributeError:
            self.select_element_from_dropdown_list_by_text_and_click(
                capture_mode,
                (By.XPATH, self._CAPTURE_MODE_DROPDOWN_BUTTON_XPATH.format(self._CAPTURE_MODE)),
                (By.XPATH, self._CAPTURE_MODE_DROPDOWN_SELECTION_XPATH.format(capture_mode))
            )
        self.click_enabled_element((By.XPATH, self._SAVE_IQ_CAPTURE_DATA_BUTTON_XPATH))


class IpSecurityAssociationsPage(NavigatablePage):
    _MENU_ROUTE_LIST = ["Diagnostic", "IP Security Associations"]

    def __init__(self, driver):
        super(IpSecurityAssociationsPage, self).__init__(driver)
        self._view_panel = IpSecurityAssociationsPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def get_ike_associations(self, timeout=60):
        return self._view_panel.get_ike_associations(timeout)

    def get_association_information(self, timeout=60):
        return self._view_panel.get_association_information(timeout)


class IpSecurityAssociationsPageViewPanel(ViewPanel):
    IKE_ASSOCIATIONS_HEADER = '//section[*[contains(text(), "IKE associations")]]//thead//th'
    IKE_ASSOCIATIONS_TR = '(//section[*[contains(text(), "IKE associations")]]//tbody//tr)'
    ASSOCIATIONS_INFO_HEADER = '//section[*[contains(text(), "Association information")]]//thead//th'
    ASSOCIATIONS_INFO_TR = '(//section[*[contains(text(), "Association information")]]//tbody//tr)'
    NO_IKE_ASSOCIATION = 'No IKE association'
    NO_ASSOCIATION_INFORMATION = 'No association information'

    def __init__(self, driver):
        super(IpSecurityAssociationsPageViewPanel, self).__init__(driver)

    def get_ike_associations(self, timeout=60):
        ike_associations = []
        key_list = self.get_fields_info_from_row(self.IKE_ASSOCIATIONS_HEADER, timeout)
        associations_number = len(self.driver.find_elements_by_xpath(self.IKE_ASSOCIATIONS_TR))
        for index in range(1, associations_number + 1):
            value_list = self.get_fields_info_from_row(self.IKE_ASSOCIATIONS_TR + '[{}]//td'.format(index), timeout)
            if self.NO_IKE_ASSOCIATION in value_list:
                ike_associations.append(dict(zip(key_list, [''] * len(key_list))))
            else:
                ike_associations.append(dict(zip(key_list, value_list)))
        return ike_associations

    def get_association_information(self, timeout=60):
        association_info = []
        key_list = self.get_fields_info_from_row(self.ASSOCIATIONS_INFO_HEADER, timeout)
        associations_number = len(self.driver.find_elements_by_xpath(self.ASSOCIATIONS_INFO_TR))
        for index in range(1, associations_number + 1):
            value_list = self.get_fields_info_from_row(self.ASSOCIATIONS_INFO_TR + '[{}]//td'.format(index), timeout)
            if self.NO_ASSOCIATION_INFORMATION in value_list:
                association_info.append(dict(zip(key_list, [''] * len(key_list))))
            else:
                association_info.append(dict(zip(key_list, value_list)))
        return association_info
